          gSprites[sGroudonShoulderSpriteId].x2 = -1;
          gSprites[sGroudonShoulderSpriteId].y2 = 1;
          gSprites[sGroudonClawSpriteId].x2 = -2;
          gSprites[sGroudonClawSpriteId].y2 = 1;
