/** static void HBlankCB_RayDescends(void) */
export function HBlankCB_RayDescends(): any {
  let vcount: any = GetGpuReg(REG_OFFSET_VCOUNT);
      if (vcount >= 24 && vcount <= 135 && vcount - 24 <= sRayScene.revealedLightLine)
          REG_BLDALPHA = 0xD08;  
      else
          REG_BLDALPHA = _0x1000;  

      if (vcount == 0)
      {
          if (sRayScene.revealedLightLine <= 0x1FFF)
          {
               
               
              if (sRayScene.revealedLightLine <= 39)
                  sRayScene.revealedLightLine += 4;
              else if (sRayScene.revealedLightLine <= 79)
                  sRayScene.revealedLightLine += 2;
              else
                  sRayScene.revealedLightLine += 1;
          }

           
          sRayScene.revealedLightTimer++;
      }
}

/** static void Task_RayDescendsAnim(u8 taskId) */
export function Task_RayDescendsAnim(taskId: any): any {
  let data: any = gTasks[taskId].data;
      InitDescendsSceneBgs();
      LoadDescendsSceneGfx();
      SetGpuRegBits(REG_OFFSET_BLDCNT, BLDCNT_TGT1_BG0 | BLDCNT_TGT2_BG1 | BLDCNT_TGT2_BG2 | BLDCNT_TGT2_BG3 | BLDCNT_TGT2_OBJ | BLDCNT_EFFECT_BLEND);
      SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(0, 16));
      BlendPalettes(PALETTES_ALL, _0x10, RGB_BLACK);
      SetVBlankCallback(VBlankCB_RayquazaScene);
      sRayScene.revealedLightLine = 0;
      sRayScene.revealedLightTimer = 0;
      tState = 0;
      tTimer = 0;
      data[2] = 0;  
      data[3] = 0;
      data[4] = _0x1000;
      gTasks[taskId].func = Task_HandleRayDescends;
}

/** static void Task_HandleRayDescends(u8 taskId) */
export function Task_HandleRayDescends(taskId: any): any {
  let data: any = gTasks[taskId].data;
      switch (tState)
      {
      case 0:
           
          if (tTimer == 8)
          {
              BeginNormalPaletteFade(PALETTES_ALL, 0, _0x10, 0, RGB_BLACK);
              tTimer = 0;
              tState++;
          }
          else
          {
              tTimer++;
          }
          break;
      case 1:
          if (!gPaletteFade.active)
          {
               
              if (tTimer == 10)
              {
                  tTimer = 0;
                  tState++;
                  SetHBlankCallback(HBlankCB_RayDescends);
                  EnableInterrupts(INTR_FLAG_HBLANK | INTR_FLAG_VBLANK);
              }
              else
              {
                  tTimer++;
              }
          }
          break;
      case 2:
           
          if (tTimer == 80)
          {
              tTimer = 0;
              tState++;
              CreateDescendsRayquazaSprite();
          }
          else
          {
              tTimer++;
          }
          break;
      case 3:
           
          if (++tTimer == 368)
          {
              tTimer = 0;
              tState++;
          }
          break;
      case 4:
           
          BeginNormalPaletteFade(PALETTES_ALL, 0, 0, _0x10, RGB_BLACK);
          gTasks[taskId].func = Task_RayDescendsEnd;
          break;
      }
}

/** static void Task_RayDescendsEnd(u8 taskId) */
export function Task_RayDescendsEnd(taskId: any): any {
  if (!gPaletteFade.active)
      {
          SetVBlankCallback(NULL);
          SetHBlankCallback(NULL);
          ResetSpriteData();
          FreeAllSpritePalettes();
          gTasks[taskId].func = Task_SetNextAnim;
      }
}

/** static u8 CreateDescendsRayquazaSprite(void) */
export function CreateDescendsRayquazaSprite(): any {
  let spriteId: any = CreateSprite(sSpriteTemplate_Descends_Rayquaza, 160, 0, 0);
      let data: any = gSprites[spriteId].data;
      sTailSpriteId = CreateSprite(sSpriteTemplate_Descends_RayquazaTail, 184, -48, 0);
      gSprites[spriteId].callback = SpriteCB_Descends_Rayquaza;
      gSprites[spriteId].oam.priority = 3;
      gSprites[sTailSpriteId].oam.priority = 3;
      return spriteId;
}

/** static void SpriteCB_Descends_Rayquaza(struct Sprite *sprite) */
export function SpriteCB_Descends_Rayquaza(sprite: any): any {
  let data: any = sprite.data;
      let frame: any = sTimer;

       
       
      if (frame == 0)
      {
          sXMovePeriod = 12;
          sYMovePeriod = 8;
      }
      else if (frame == 256)
      {
          sXMovePeriod = 9;
          sYMovePeriod = 7;
      }
      else if (frame == 268)
      {
          sXMovePeriod = 8;
          sYMovePeriod = 6;
      }
      else if (frame == 280)
      {
          sXMovePeriod = 7;
          sYMovePeriod = 5;
      }
      else if (frame == 292)
      {
          sXMovePeriod = 6;
          sYMovePeriod = 4;
      }
      else if (frame == 304)
      {
          sXMovePeriod = 5;
          sYMovePeriod = 3;
      }
      else if (frame == 320)
      {
          sXMovePeriod = 4;
          sYMovePeriod = 2;
      }

      if (sTimer % sXMovePeriod == 0)
      {
          sprite.x2--;
          gSprites[sTailSpriteId].x2--;
      }
      if (sTimer % sYMovePeriod == 0)
      {
          sprite.y2++;
          gSprites[sTailSpriteId].y2++;
      }

      sTimer++;
}

